mapper.select:
select WTPD.TRADE_ID tradeId, #{VALID_STATUS_01} validStatus, WTPDA.ENTRUST_ID entrustId, WTPDA.PORTFOLIO_ID portfolioId, PP.PORTFOLIO_NAME portfolioName, WTPDA.EXC_DEAL_TYPE excDealType, WTPDA.CUR_PAIR curPair, WTPDO.EXC_PS ps, WTPD.DELIVERY_TYPE deliveryType, WTPD.TRADE_DATE tradeDate, WTPDO.TERM_TYPE termType, WTPDO.F_MDATE settleDate, WTPD.UNIT_CPRICE unitCprice, WTPD.UNIT_INT unitInt, WTPD.UNIT_FPRICE unitFprice, WTPDA.PRICED_DATE pricedDate, WTPDA.PRICED_DATE_RATE pricedDateRate, WTPDA.DIF_PS difPs, WTPDA.DIF_PAY_AMT difPayAmt, WTPDO.DEAL_CUR ccy, WTPD.PRIN_AMT prinAmt, WTPD.CCY corCcy, WTPD.FPRICE_AMT fpriceAmt, WTPDA.USD_AMT usdAmt, WTPD.REMARK remark, WTPD.WORKFLOW_ID workflowId, WTPD.WORKFLOW_STATUS workflowStatus, WTPD.FINPROD_TYPE2 finprodType2, WTPD.FINPROD_ID finprodId, null tradeId1 from WFL_TRD_PRODUCT_DEAL WTPD left join WFL_TRD_PRODUCT_DEAL_ADD WTPDA on WTPD.TRADE_ID = WTPDA.TRADE_ID left join PTL_PORTFOLIO PP on PP.PORTFOLIO_ID = WTPDA.PORTFOLIO_ID left join WFL_TRD_PRODUCT_DEAL_OTH WTPDO on WTPD.TRADE_ID = WTPDO.TRADE_ID where WTPD.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F12} AND WTPD.PS = #{PS_T01}
AND (PP.PORTFOLIO_ID IN
#{item}
or PP.PARENT_PORTFOLIO_ID IN
#{item}
)
and ( PP.PORTFOLIO_ID in (select PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY where USER_ID = #{loginUserName}) OR PP.PARENT_PORTFOLIO_ID in (select PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY where USER_ID = #{loginUserName}) )
AND WTPDA.ENTRUST_ID like CONCAT(#{entrustId}, '%')
AND WTPDA.EXC_DEAL_TYPE = #{excDealType}
AND WTPDA.CUR_PAIR = #{curPair}
AND WTPD.DELIVERY_TYPE = #{deliveryType}
AND WTPDO.EXC_PS IN
#{item}
AND WTPD.TRADE_DATE >= to_date(#{tradeDateBegin}, 'yyyy-MM-dd')
AND WTPD.TRADE_DATE <= to_date(#{tradeDateEnd}, 'yyyy-MM-dd')
AND WTPDO.F_MDATE >= to_date(#{settleDateBegin}, 'yyyy-MM-dd')
AND WTPDO.F_MDATE <= to_date(#{settleDateEnd}, 'yyyy-MM-dd')
and WTPD.TRADE_STATUS = #{TRADE_STATUS_01}
UNION ALL select TPD.TRADE_ID tradeId, #{VALID_STATUS_02} validStatus, TPDA.ENTRUST_ID entrustId, PP.PORTFOLIO_ID portfolioId, PP.PORTFOLIO_NAME portfolioName, TPDA.EXC_DEAL_TYPE excDealType, TPDA.CUR_PAIR curPair, FTP.EXC_PS ps, TPD.DELIVERY_TYPE deliveryType, TPD.TRADE_DATE tradeDate, FTP.TERM_TYPE termType, FTP.MDATE settleDate, TPD.UNIT_CPRICE unitCprice, TPD.UNIT_INT unitInt, TPD.UNIT_FPRICE unitFprice, TPDA.PRICED_DATE pricedDate, TPDA1.PRICED_DATE_RATE pricedDateRate, TPDA1.DIF_PS difPs, TPDA1.DIF_PAY_AMT difPayAmt, FTP.CCY ccy, TPD.PRIN_AMT prinAmt, TPD.CCY corCcy, TPD.FPRICE_AMT fpriceAmt, TPDA.USD_AMT usdAmt, TPD.REMARK remark, NULL workflowId, NULL workflowStatus, TPD.FINPROD_TYPE2 finprodType2, TPD.FINPROD_ID finprodId, NULL tradeId1 from TRD_PRODUCT_DEAL TPD left join TRD_PRODUCT_DEAL_ADD TPDA on TPD.TRADE_ID = TPDA.TRADE_ID LEFT JOIN PTL_TRADE PT ON TPD.TRADE_ID = PT.BUSI_NO left join PTL_PORTFOLIO PP on PP.PORTFOLIO_ID = PT.PORTFOLIO_ID left join FIN_TRADE_PRODUCT FTP on FTP.FINPROD_ID = TPD.FINPROD_ID left join TRD_PRODUCT_DEAL TPD1 on FTP.FINPROD_ID = TPD1.FINPROD_ID and TPD1.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F12} and TPD1.PS = #{PS_T07} and TPD1.TRADE_STATUS = #{TRADE_STATUS_01} left join TRD_PRODUCT_DEAL_ADD TPDA1 on TPD1.TRADE_ID = TPDA1.TRADE_ID WHERE TPD.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F12} AND TPD.PS = #{PS_T01} AND PP.INVEST_YESORNO='Y'
AND (PP.PORTFOLIO_ID IN
#{item}
OR PP.PARENT_PORTFOLIO_ID IN
#{item}
)
and (PP.PORTFOLIO_ID in (select PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY where USER_ID = #{loginUserName}) OR PP.PARENT_PORTFOLIO_ID in (select PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY where USER_ID = #{loginUserName}))
AND TPDA.ENTRUST_ID like CONCAT(#{entrustId}, '%')
AND TPDA.EXC_DEAL_TYPE = #{excDealType}
AND TPDA.CUR_PAIR = #{curPair}
AND TPD.DELIVERY_TYPE = #{deliveryType}
AND FTP.EXC_PS IN
#{item}
AND TPD.TRADE_DATE >= to_date(#{tradeDateBegin}, 'yyyy-MM-dd')
AND TPD.TRADE_DATE <= to_date(#{tradeDateEnd}, 'yyyy-MM-dd')
AND FTP.MDATE >= to_date(#{settleDateBegin}, 'yyyy-MM-dd')
AND FTP.MDATE <= to_date(#{settleDateEnd}, 'yyyy-MM-dd')
and (TPD.IS_CANCEL is null or TPD.IS_CANCEL = #{YES_NO_NO}) and TPD.TRADE_STATUS = #{TRADE_STATUS_01}
UNION ALL select TPD.TRADE_ID tradeId, #{VALID_STATUS_03} validStatus, TPDA.ENTRUST_ID entrustId, PP.PORTFOLIO_ID portfolioId, PP.PORTFOLIO_NAME portfolioName, TPDA.EXC_DEAL_TYPE excDealType, TPDA.CUR_PAIR curPair, FTP.EXC_PS ps, TPD.DELIVERY_TYPE deliveryType, TPD.TRADE_DATE tradeDate, FTP.TERM_TYPE termType, FTP.MDATE settleDate, TPD.UNIT_CPRICE unitCprice, TPD.UNIT_INT unitInt, TPD.UNIT_FPRICE unitFprice, TPDA.PRICED_DATE pricedDate, TPDA1.PRICED_DATE_RATE pricedDateRate, TPDA1.DIF_PS difPs, TPDA1.DIF_PAY_AMT difPayAmt, FTP.CCY ccy, TPD.PRIN_AMT prinAmt, TPD.CCY corCcy, TPD.FPRICE_AMT fpriceAmt, TPDA.USD_AMT usdAmt, TPD.REMARK remark, NULL workflowId, NULL workflowStatus, TPD.FINPROD_TYPE2 finprodType2, TPD.FINPROD_ID finprodId, NULL tradeId1 from TRD_PRODUCT_DEAL TPD left join TRD_PRODUCT_DEAL_ADD TPDA on TPD.TRADE_ID = TPDA.TRADE_ID LEFT JOIN PTL_TRADE PT ON TPD.P_TRADE_ID = PT.BUSI_NO left join PTL_PORTFOLIO PP on PP.PORTFOLIO_ID = PT.PORTFOLIO_ID left join FIN_TRADE_PRODUCT FTP on FTP.FINPROD_ID = TPD.FINPROD_ID left join TRD_PRODUCT_DEAL TPD1 on FTP.FINPROD_ID = TPD1.FINPROD_ID and TPD1.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F12} and TPD1.PS = #{PS_T07} and TPD1.TRADE_STATUS = #{TRADE_STATUS_03} left join TRD_PRODUCT_DEAL_ADD TPDA1 on TPD1.TRADE_ID = TPDA1.TRADE_ID WHERE TPD.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F12} AND TPD.PS = #{PS_T01} AND PP.INVEST_YESORNO='Y'
AND (PP.PORTFOLIO_ID IN
#{item}
OR PP.PARENT_PORTFOLIO_ID IN
#{item}
)
and (PP.PORTFOLIO_ID in (select PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY where USER_ID = #{loginUserName}) or PP.PARENT_PORTFOLIO_ID in (select PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY where USER_ID = #{loginUserName}) )
AND TPDA.ENTRUST_ID like CONCAT(#{entrustId}, '%')
AND TPDA.EXC_DEAL_TYPE = #{excDealType}
AND TPDA.CUR_PAIR = #{curPair}
AND TPD.DELIVERY_TYPE = #{deliveryType}
AND FTP.EXC_PS IN
#{item}
AND TPD.TRADE_DATE >= to_date(#{tradeDateBegin}, 'yyyy-MM-dd')
AND TPD.TRADE_DATE <= to_date(#{tradeDateEnd}, 'yyyy-MM-dd')
AND FTP.MDATE >= to_date(#{settleDateBegin}, 'yyyy-MM-dd')
AND FTP.MDATE <= to_date(#{settleDateEnd}, 'yyyy-MM-dd')
and TPD.IS_CANCEL != #{YES_NO_YES} and TPD.TRADE_STATUS = #{TRADE_STATUS_03}
ORDER BY tradeDate DESC, tradeId DESC
